#pragma once

// Built-in reader fonts (KoPub Batang Medium, KS X 1001 Hangul, compressed).
// Generated by lib/EpdFont/scripts/convert-bible-fonts.sh, registered in main.cpp.

#define BIBLE_14_FONT_ID (-1446433084)  // same id the reader font always had
#define BIBLE_17_FONT_ID (-1446433017)
#define BIBLE_20_FONT_ID (-1446433020)
#define BIBLE_24_FONT_ID (-1446433024)
#define BIBLE_28_FONT_ID (-1446433028)

namespace BibleFonts {

constexpr int COUNT = 5;
constexpr int IDS[COUNT] = {BIBLE_14_FONT_ID, BIBLE_17_FONT_ID, BIBLE_20_FONT_ID, BIBLE_24_FONT_ID,
                            BIBLE_28_FONT_ID};
constexpr int POINTS[COUNT] = {14, 17, 20, 24, 28};

inline int fontId(int sizeIndex) {
  if (sizeIndex < 0) sizeIndex = 0;
  if (sizeIndex >= COUNT) sizeIndex = COUNT - 1;
  return IDS[sizeIndex];
}

// Chrome on Bible screens (headers, page numbers, labels).
constexpr int LABEL_FONT_ID = BIBLE_14_FONT_ID;

}  // namespace BibleFonts
